from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any, Union


class Errno(Enum):
    """Closed errno set (SSOT for all three SDKs). Wire spelling is the
    SCREAMING POSIX name (EPERM, EACCES), except E_CONFIG,
    E_SECURITY_VIOLATION, E_UNKNOWN_KIND, E_CLOCK_REGRESS, and
    PATH_TRAVERSAL, which keep their mixed-case wire spelling. There is
    no silent fallback: an unrecognized name is not an errno, and no
    hook boundary accepts a bare string errno.

    PATH_TRAVERSAL is the one traversal-specific member: a lookup that
    escapes the declared root denies with Action.drop carrying
    Errno.PATH_TRAVERSAL, and the driver maps it to EPERM before it
    surfaces to the guest (the guest never sees a non-POSIX traversal
    errno).
    """

    EPERM = "EPERM"
    EACCES = "EACCES"
    ENOENT = "ENOENT"
    EINVAL = "EINVAL"
    ENOSPC = "ENOSPC"
    EROFS = "EROFS"
    ECONNREFUSED = "ECONNREFUSED"
    ENXIO = "ENXIO"
    EWOULDBLOCK = "EWOULDBLOCK"
    EFAULT = "EFAULT"
    EBUSY = "EBUSY"
    EXDEV = "EXDEV"
    EPIPE = "EPIPE"
    ENODATA = "ENODATA"
    EPROTO = "EPROTO"
    EPOLICY = "EPOLICY"
    ETOOLQUOTA = "ETOOLQUOTA"
    EWXVIOLATION = "EWXVIOLATION"
    E_CONFIG = "EConfig"
    E_SECURITY_VIOLATION = "ESecurityViolation"
    E_UNKNOWN_KIND = "EUnknownKind"
    E_CLOCK_REGRESS = "EClockRegress"
    PATH_TRAVERSAL = "PathTraversal"


class SuspendUntil:
    """Hold primitive for Action.suspend. Deadline is in milliseconds."""

    __slots__ = ("_kind", "_ms")

    def __init__(self, kind: str, ms: int | None = None) -> None:
        self._kind = kind
        self._ms = ms

    @classmethod
    def deadline(cls, ms: int) -> "SuspendUntil":
        return cls("deadline", ms)

    @classmethod
    def approval(cls) -> "SuspendUntil":
        return cls("approval")

    @classmethod
    def handshake(cls) -> "SuspendUntil":
        return cls("handshake")


# Idioms kept from the live Python SDK: Deadline/Approval/Handshake
# callables mirror SuspendUntil.deadline/approval/handshake.

def Deadline(ms: int) -> SuspendUntil:
    return SuspendUntil.deadline(ms)


def Approval() -> SuspendUntil:
    return SuspendUntil.approval()


def Handshake() -> SuspendUntil:
    return SuspendUntil.handshake()


