PatchPayload = Union[Any, FsInode, Custom]


@dataclass(frozen=True)
class Action:
    """The unified action algebra: one enum for every interposer hook
    return (02-plugin-model #Unified-verdict). Denial is Action.drop;
    fatal termination is Action.abort; both are actions, never errors.

    Ring restriction is enforced by the ring trait's return type, not
    by this class: on_fs_write accepts only forward | drop | suspend |
    abort; on_fs_lookup accepts only pass | drop | suspend | abort |
    patch. There is no patch on filter rings: the transformed buffer IS
    the payload.
    """

    kind: str
    errno: Errno | None = None
    reason: str | None = None
    until: SuspendUntil | None = None
    payload: Any = None

    @classmethod
    def pass_(cls) -> "Action":
        # `pass` is a keyword; the factory spelling is pass_. The
        # ready-made Pass attribute below is the sugar form.
        return cls(kind="pass")

    @classmethod
    def forward(cls) -> "Action":
        return cls(kind="forward")

    @classmethod
    def drop(cls, errno: Errno, reason: str) -> "Action":
        return cls(kind="drop", errno=errno, reason=reason)

    @classmethod
    def suspend(cls, until: SuspendUntil) -> "Action":
        return cls(kind="suspend", until=until)

    @classmethod
    def abort(cls, reason: str) -> "Action":
        return cls(kind="abort", reason=reason)

    @classmethod
    def patch(cls, payload: Any) -> "Action":
        return cls(kind="patch", payload=payload)


# `pass` is a Python keyword: an attribute named `pass` cannot be written
# in source at all, even as a method call (c.pass() is a SyntaxError).
# The SDK sugar is the uppercase class attribute Pass, matching the live
# Verdict.Pass alias (packages/py/kelir/__init__.py), plus the pass_()
# factory. Rust and TS spell it c.pass(); Python is the keyword outlier.
Action.Pass = Action.pass_()  # ready-made pass action: Verdict.Pass


# Type aliases, not separate enums: the Verdict / FilterAction split
# collapses onto Action here. Old call sites keep resolving; new code
# writes Action directly. No third alias exists, and a raised handler
# exception never carries a policy denial (PluginError-scope pin).
Verdict = Action
FilterAction = Action
